-- ============================================================
-- NAHUALES (20 signos del calendario Cholq'ij)
-- ============================================================
INSERT INTO public.nahuales (index_num, nombre, significado, descripcion, elemento, animal_guia, punto_cardinal, color_maiz, parte_cuerpo, lugar_poder, elemento_conexion, cualidades, sombras) VALUES

(1, 'Imox', 'Agua / Sueños', 'Imox representa el lado izquierdo del cerebro, lo inusual, lo excéntrico. Es la energía de los sueños y el subconsciente. Las personas nacidas bajo este signo tienen una conexión profunda con el mundo espiritual y poseen una sensibilidad extraordinaria. Son creativos, intuitivos y tienen la capacidad de percibir lo que otros no pueden ver. El agua es su elemento, representando la fluidez emocional y la capacidad de adaptación.', 'Agua', 'Lagarto', 'Este', 'Rojo', 'Sangre', 'Lagos y ríos', 'Agua ceremonial', ARRAY['Intuitivo', 'Creativo', 'Sensible', 'Visionario', 'Adaptable'], ARRAY['Inestabilidad emocional', 'Tendencia al escapismo', 'Dificultad para concretar', 'Hipersensibilidad', 'Confusión mental']),

(2, 'Iq''', 'Viento / Comunicación', 'Iq'' es el soplo de vida, el viento sagrado que comunica los mensajes entre el cielo y la tierra. Representa la comunicación, la respiración y el espíritu. Las personas de este signo son mensajeros naturales, con una capacidad innata para transmitir ideas y conectar personas. Poseen una mente ágil y cambiante como el viento, con gran habilidad para adaptarse a diferentes situaciones.', 'Aire', 'Colibrí', 'Norte', 'Blanco', 'Respiración', 'Cimas de montañas', 'Viento sagrado', ARRAY['Comunicativo', 'Ágil', 'Mensajero', 'Versátil', 'Espiritual'], ARRAY['Inconstancia', 'Superficialidad', 'Tendencia al chisme', 'Dispersión mental', 'Cambios de humor repentinos']),

(3, 'Aq''ab''al', 'Amanecer / Dualidad', 'Aq''ab''al simboliza el amanecer, el momento sagrado entre la noche y el día. Representa la dualidad, los nuevos comienzos y la renovación. Quienes nacen bajo este signo tienen el don de ver ambos lados de cada situación. Son personas de transición, capaces de traer luz a la oscuridad y comprensión donde hay confusión. Poseen una sabiduría especial para guiar a otros en momentos de cambio.', 'Luz y Oscuridad', 'Murciélago', 'Oeste', 'Negro', 'Ojos', 'Cuevas sagradas', 'Luz del amanecer', ARRAY['Renovador', 'Equilibrado', 'Sabio', 'Guía', 'Transformador'], ARRAY['Dualidad interna conflictiva', 'Dificultad para tomar decisiones', 'Tendencia a la ambigüedad', 'Ocultamiento de verdades', 'Vivir entre dos mundos sin definirse']),

(4, 'K''at', 'Red / Abundancia', 'K''at es la red que atrapa y guarda, representa la abundancia, la cosecha y la capacidad de manifestar. Es el signo de quienes saben guardar y multiplicar. Las personas K''at tienen un talento natural para atraer prosperidad y crear redes de apoyo. Sin embargo, deben cuidar de no caer en el apego material. Su lección es aprender a fluir con la abundancia, dando y recibiendo en equilibrio.', 'Fuego', 'Araña', 'Sur', 'Amarillo', 'Manos', 'Selvas tropicales', 'Red de conexión cósmica', ARRAY['Abundante', 'Conectador', 'Manifestador', 'Generoso', 'Próspero'], ARRAY['Apego material excesivo', 'Tendencia a acumular', 'Dificultad para soltar', 'Enredarse en problemas ajenos', 'Codicia o avaricia']),

(5, 'Kan', 'Serpiente / Energía Vital', 'Kan es la serpiente emplumada, símbolo de la energía kundalini y la fuerza vital. Representa la evolución espiritual, la justicia y la verdad. Las personas nacidas bajo Kan poseen una energía magnética y una presencia poderosa. Son líderes naturales con una capacidad innata para inspirar a otros. La serpiente les enseña a mudar de piel, a transformarse y evolucionar constantemente hacia versiones más elevadas de sí mismos.', 'Fuego', 'Quétzal', 'Este', 'Rojo', 'Columna vertebral', 'Templos sagrados', 'Fuego kundalini', ARRAY['Poderoso', 'Transformador', 'Líder', 'Magnético', 'Evolutivo'], ARRAY['Orgullo excesivo', 'Manipulación', 'Celos intensos', 'Ira descontrolada', 'Uso del poder para dominar']),

(6, 'Kame', 'Transformación / Ancestros', 'Kame representa la muerte como transformación, no como final. Es el signo de los ancestros, la memoria y la conexión con quienes ya partieron. Las personas Kame tienen un vínculo especial con el mundo espiritual y frecuentemente reciben mensajes de sus antepasados. Poseen el don de la clarividencia y una comprensión profunda de los ciclos de la vida. Son guardianes de la tradición y la sabiduría ancestral.', 'Tierra', 'Lechuza', 'Norte', 'Blanco', 'Huesos', 'Cementerios ancestrales', 'Portal ancestral', ARRAY['Clarividente', 'Ancestral', 'Protector', 'Sabio', 'Transformador'], ARRAY['Miedo a la muerte o al cambio', 'Pesimismo', 'Quedarse atrapado en el pasado', 'Pensamientos morbidos', 'Dificultad para avanzar']),

(7, 'Kej', 'Venado / Naturaleza', 'Kej es el venado sagrado, guardián de los bosques y símbolo de la armonía con la naturaleza. Representa los cuatro pilares del universo, la fuerza y la elegancia. Las personas nacidas bajo Kej son protectores naturales con una conexión profunda con los animales y la tierra. Poseen gracia, agilidad mental y física, y un sentido innato de orientación. Son líderes serenos que guían con el ejemplo.', 'Aire', 'Venado', 'Oeste', 'Negro', 'Extremidades', 'Bosques sagrados', 'Naturaleza viva', ARRAY['Protector', 'Elegante', 'Líder sereno', 'Armonioso', 'Fuerte'], ARRAY['Rigidez mental', 'Terquedad', 'Distanciamiento emocional', 'Dificultad para pedir ayuda', 'Aislamiento autoimpuesto']),

(8, 'Q''anil', 'Semilla / Vida', 'Q''anil es la semilla, el potencial infinito de la vida. Representa la fertilidad, la abundancia y todo lo que está por germinar. Las personas Q''anil son sembradoras naturales, ya sea de ideas, proyectos o vida. Tienen el don de nutrir y hacer crecer todo lo que tocan. Son optimistas por naturaleza y poseen una fe inquebrantable en el futuro. Su energía es de renacimiento y nuevos comienzos.', 'Tierra', 'Conejo', 'Sur', 'Amarillo', 'Órganos reproductivos', 'Campos de cultivo', 'Semilla sagrada', ARRAY['Fértil', 'Optimista', 'Nutridor', 'Renovador', 'Esperanzador'], ARRAY['Exceso de optimismo irreal', 'Impaciencia por ver resultados', 'Dispersión de energía', 'Iniciar sin terminar', 'Ingenuidad que lleva a decepciones']),

(9, 'Toj', 'Ofrenda / Fuego Sagrado', 'Toj representa la ofrenda, el pago sagrado y el equilibrio kármico. Es el fuego ceremonial que purifica y transforma. Las personas nacidas bajo Toj comprenden intuitivamente la ley del dar y recibir. Son generosas y tienen una conexión profunda con lo ceremonial y lo sagrado. Poseen el don de la sanación emocional y la capacidad de restaurar el equilibrio en situaciones de conflicto.', 'Fuego', 'Fuego', 'Este', 'Rojo', 'Oídos', 'Altares ceremoniales', 'Fuego ceremonial', ARRAY['Generoso', 'Equilibrador', 'Sanador', 'Ceremonial', 'Agradecido'], ARRAY['Culpa excesiva', 'Sentirse en deuda constante', 'Sacrificio excesivo por otros', 'Complejo de mártir', 'Dificultad para recibir']),

(10, 'Tz''i''', 'Justicia / Ley', 'Tz''i'' es el perro, guardián de la ley divina y la justicia. Representa la fidelidad, la lealtad y la verdad. Las personas nacidas bajo este signo tienen un sentido innato de lo correcto y lo incorrecto. Son defensores naturales de los desfavorecidos y buscan siempre el equilibrio y la justicia. Poseen una lealtad inquebrantable hacia quienes aman y una capacidad especial para discernir la verdad.', 'Agua', 'Perro/Coyote', 'Norte', 'Blanco', 'Nariz', 'Tribunales de justicia', 'Ley cósmica', ARRAY['Justo', 'Leal', 'Verdadero', 'Fiel', 'Defensor'], ARRAY['Ser demasiado crítico', 'Juzgar duramente a otros', 'Obsesión con la justicia', 'Inflexibilidad moral', 'Dificultad para perdonar']),

(11, 'B''atz''', 'Hilo del Tiempo / Arte', 'B''atz'' es el mono artesano, tejedor del tiempo y creador de la vida. Representa el arte, la creatividad y el hilo que conecta todo en el universo. Es el primer día del calendario sagrado Cholq''ij. Las personas B''atz'' son artistas naturales con una capacidad extraordinaria para crear belleza en todas sus formas. Poseen el don de ver los patrones ocultos de la vida y tejer destinos con sus manos creativas.', 'Aire', 'Mono', 'Oeste', 'Negro', 'Dedos', 'Talleres artísticos', 'Hilo del tiempo', ARRAY['Artístico', 'Creativo', 'Tejedor', 'Visionario', 'Maestro'], ARRAY['Vanidad artística', 'Perfeccionismo paralizante', 'Manipulación sutil', 'Enredarse en dramas', 'Dificultad para simplificar']),

(12, 'E', 'Camino / Destino', 'E es el camino sagrado, la ruta del destino y la guía divina. Representa los viajes, tanto físicos como espirituales, y la búsqueda del propósito. Las personas nacidas bajo E son viajeros eternos, exploradores de mundos internos y externos. Tienen el don de encontrar su camino incluso en la oscuridad y de guiar a otros hacia su destino. Son buscadores de verdad con una curiosidad insaciable.', 'Tierra', 'Gato Montés', 'Sur', 'Amarillo', 'Pies', 'Caminos sagrados', 'Sendero sagrado', ARRAY['Explorador', 'Guía', 'Buscador', 'Curioso', 'Orientador'], ARRAY['Inquietud constante', 'Incapacidad para echar raíces', 'Huir de compromisos', 'Perderse en búsquedas sin fin', 'Inestabilidad de vida']),

(13, 'Aj', 'Caña / Hogar', 'Aj representa la caña de maíz, el pilar central del hogar y la familia. Es el signo de la autoridad, la tradición y la columna vertebral de la comunidad. Las personas Aj son pilares de fortaleza para quienes los rodean. Tienen un profundo sentido de responsabilidad familiar y una conexión especial con sus raíces. Son constructores de hogares, tanto físicos como emocionales, y guardianes de las tradiciones.', 'Fuego', 'Armadillo', 'Este', 'Rojo', 'Espalda', 'Hogares ancestrales', 'Pilar central', ARRAY['Protector familiar', 'Tradicional', 'Fuerte', 'Responsable', 'Arraigado'], ARRAY['Rigidez en tradiciones', 'Autoritarismo familiar', 'Resistencia al cambio', 'Cargar responsabilidades ajenas', 'Control excesivo del hogar']),

(14, 'I''x', 'Jaguar / Magia Femenina', 'I''x es el jaguar, guardián de la noche y símbolo del poder femenino. Representa la magia, la intuición y la fuerza interior. Las personas nacidas bajo I''x poseen una energía misteriosa y magnética. Son intuitivos naturales con acceso a conocimientos ocultos. El jaguar les otorga la capacidad de moverse entre mundos y de ver en la oscuridad lo que otros no pueden percibir. Son protectores de lo sagrado.', 'Tierra', 'Jaguar', 'Norte', 'Blanco', 'Músculos', 'Selvas nocturnas', 'Magia lunar', ARRAY['Misterioso', 'Intuitivo', 'Poderoso', 'Mágico', 'Protector'], ARRAY['Secretismo excesivo', 'Manipulación oculta', 'Uso incorrecto del poder', 'Desconfianza crónica', 'Tendencia a la venganza silenciosa']),

(15, 'Tz''ikin', 'Águila / Visión', 'Tz''ikin es el águila y el quetzal, mensajeros entre el cielo y la tierra. Representa la visión, la libertad y la conexión con el Gran Espíritu. Las personas Tz''ikin tienen una perspectiva elevada de la vida y la capacidad de ver el panorama completo. Son visionarios naturales con el don de la prosperidad y la abundancia. El águila les otorga la libertad de espíritu y la capacidad de elevarse sobre los problemas.', 'Aire', 'Águila/Quetzal', 'Oeste', 'Negro', 'Ojos', 'Cimas y cielos', 'Visión cósmica', ARRAY['Visionario', 'Libre', 'Próspero', 'Elevado', 'Mensajero divino'], ARRAY['Materialismo excesivo', 'Orgullo por logros', 'Sueños poco realistas', 'Desconexión de lo terrenal', 'Soberbia espiritual']),

(16, 'Ajmaq', 'Perdón / Sabiduría', 'Ajmaq representa el perdón, la sabiduría de los ancestros y la conexión con los que ya partieron. Es el signo de la introspección y la búsqueda de respuestas profundas. Las personas Ajmaq tienen acceso a la sabiduría antigua y una comprensión profunda de los misterios de la vida y la muerte. Poseen el don del perdón y la capacidad de sanar heridas del pasado, tanto propias como ajenas.', 'Tierra', 'Abeja', 'Sur', 'Amarillo', 'Memoria', 'Cuevas ancestrales', 'Perdón divino', ARRAY['Sabio', 'Perdonador', 'Ancestral', 'Introspectivo', 'Sanador'], ARRAY['Culpa crónica', 'Secretos que pesan', 'Evitar responsabilidades', 'Vivir en el pasado', 'Dificultad para perdonarse']),

(17, 'No''j', 'Conocimiento / Ciencia', 'No''j representa el conocimiento, la sabiduría y el movimiento del pensamiento. Es el signo de la inteligencia y la capacidad de comprensión profunda. Las personas No''j son pensadores naturales con una mente analítica y curiosa. Tienen el don de comprender conceptos complejos y de encontrar soluciones innovadoras. Son buscadores de conocimiento con una sed insaciable de aprender y enseñar.', 'Aire', 'Pájaro Carpintero', 'Este', 'Rojo', 'Cerebro', 'Bibliotecas y templos de conocimiento', 'Conocimiento ancestral', ARRAY['Inteligente', 'Analítico', 'Curioso', 'Innovador', 'Maestro'], ARRAY['Sobre-análisis paralizante', 'Orgullo intelectual', 'Desconexión emocional', 'Frialdad en relaciones', 'Menospreciar la intuición']),

(18, 'Tijax', 'Obsidiana / Sanación', 'Tijax es la obsidiana, el cuchillo de doble filo que corta y sana. Representa la medicina, la cirugía espiritual y la capacidad de eliminar lo que no sirve. Las personas Tijax son sanadores naturales con el poder de cortar energías negativas y restaurar la salud. Poseen una mente aguda y la capacidad de ir directo al corazón de los problemas. Son guerreros espirituales que luchan por el bienestar de todos.', 'Fuego', 'Cuchillo de Obsidiana', 'Norte', 'Blanco', 'Lengua', 'Lugares de sanación', 'Obsidiana sagrada', ARRAY['Sanador', 'Guerrero', 'Directo', 'Cortante', 'Purificador'], ARRAY['Palabras hirientes', 'Agresividad verbal', 'Cortar relaciones bruscamente', 'Crueldad involuntaria', 'Dificultad para ser sutil']),

(19, 'Kawoq', 'Tormenta / Comunidad', 'Kawoq es la tormenta, la fuerza transformadora que limpia y renueva. Representa la comunidad, la familia extendida y el poder del grupo. Las personas Kawoq son líderes comunitarios con una capacidad innata para unir a las personas. Tienen el don de la fertilidad en todos los sentidos y la capacidad de nutrir a grandes grupos. Son protectores del bienestar colectivo y catalizadores de cambio social.', 'Agua', 'Tortuga', 'Oeste', 'Negro', 'Corazón', 'Centros comunitarios', 'Tormenta purificadora', ARRAY['Comunitario', 'Nutridor', 'Protector', 'Transformador', 'Unificador'], ARRAY['Involucrarse demasiado en vidas ajenas', 'Chisme comunitario', 'Dependencia del grupo', 'Perder identidad propia', 'Conflictos familiares recurrentes']),

(20, 'Ajpu', 'Sol / Cazador', 'Ajpu es el sol, el cazador divino y héroe gemelo del Popol Vuh. Representa la luz, la claridad y la victoria sobre la oscuridad. Las personas Ajpu son guerreros de luz con una misión clara de servicio. Poseen carisma natural y la capacidad de inspirar a otros hacia sus propósitos más elevados. El sol les otorga vitalidad, certeza y la fuerza para superar cualquier adversidad con gracia y determinación.', 'Fuego', 'Guardián del Sol', 'Sur', 'Amarillo', 'Pecho', 'Pirámides solares', 'Luz solar', ARRAY['Guerrero de luz', 'Carismático', 'Victorioso', 'Inspirador', 'Certero'], ARRAY['Ego inflado', 'Necesidad de reconocimiento', 'Arrogancia', 'Dificultad para aceptar derrotas', 'Quemar a otros con su intensidad']);

-- ============================================================
-- TONOS (13 tonos del calendario)
-- ============================================================
INSERT INTO public.tonos (numero, nombre, significado, descripcion, cualidades) VALUES
(1,  'Jun',       'Inicio',          'La unidad, el principio de todo. Representa nuevos comienzos y el potencial ilimitado.',                                                         ARRAY['Pionero', 'Iniciador', 'Valiente', 'Original']),
(2,  'Keb''',     'Dualidad',        'La polaridad, el complemento. Representa las relaciones, la cooperación y el equilibrio entre opuestos.',                                       ARRAY['Cooperador', 'Diplomático', 'Equilibrado', 'Sensible']),
(3,  'Oxib''',    'Acción',          'El movimiento, la creatividad. Representa la comunicación, la expresión y la acción decidida.',                                                  ARRAY['Comunicativo', 'Expresivo', 'Activo', 'Creativo']),
(4,  'Kajib''',   'Estabilidad',     'Los cuatro puntos cardinales. Representa la estabilidad, la estructura y los cimientos sólidos.',                                               ARRAY['Estructurado', 'Estable', 'Organizado', 'Firme']),
(5,  'Job''',     'Empoderamiento',  'El centro, el poder personal. Representa el empoderamiento, la acción y la fuerza interior.',                                                   ARRAY['Empoderado', 'Central', 'Fuerte', 'Determinado']),
(6,  'Waqib''',   'Flujo',           'La responsabilidad, el equilibrio. Representa el flujo natural, las relaciones familiares y la armonía.',                                       ARRAY['Armonioso', 'Responsable', 'Familiar', 'Fluido']),
(7,  'Wuqub''',   'Reflexión',       'El misticismo, la perfección. Representa la reflexión profunda, la espiritualidad y la conexión divina.',                                       ARRAY['Místico', 'Reflexivo', 'Espiritual', 'Perfeccionista']),
(8,  'Wajxaqib''', 'Justicia',       'La armonía, la organización. Representa la justicia, el karma y el equilibrio cósmico.',                                                       ARRAY['Justo', 'Organizador', 'Armónico', 'Kármico']),
(9,  'B''elejeb''', 'Paciencia',     'La plenitud, la vida. Representa la paciencia, la persistencia y la culminación de ciclos.',                                                    ARRAY['Paciente', 'Persistente', 'Pleno', 'Completador']),
(10, 'Lajuj',     'Manifestación',   'La manifestación, la cooperación. Representa la materialización de deseos y el trabajo en equipo.',                                             ARRAY['Manifestador', 'Colaborador', 'Materializador', 'Equipo']),
(11, 'Junlajuj',  'Liberación',      'La resolución, la liberación. Representa la disolución de obstáculos y la libertad espiritual.',                                               ARRAY['Liberador', 'Resolutivo', 'Libre', 'Desapegado']),
(12, 'Kab''lajuj', 'Entendimiento',  'La comprensión, la estabilidad. Representa el entendimiento profundo y la sabiduría madura.',                                                  ARRAY['Comprensivo', 'Maduro', 'Sabio', 'Estable']),
(13, 'Oxlajuj',   'Ascensión',       'La transformación suprema. Representa la ascensión espiritual, la conexión cósmica y la trascendencia.',                                        ARRAY['Trascendente', 'Cósmico', 'Elevado', 'Transformador']);

